glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec2 p = uv; p.x *= uRatio;
  vec2 a = vec2((0.15 + 0.25 * sin(uTime * 0.7)) * uRatio, 0.85 + 0.1 * cos(uTime * 0.5));
  vec2 b = vec2(0.95 * uRatio, 0.2 + 0.2 * sin(uTime * 0.4));
  vec3 leak = vec3(1.0, 0.45, 0.15) * smoothstep(0.9, 0.0, distance(p, a))
            + vec3(1.0, 0.2, 0.45) * smoothstep(0.8, 0.0, distance(p, b)) * 0.7;
  vec3 screen = 1.0 - (1.0 - c.rgb) * (1.0 - leak);
  return vec4(mix(c.rgb, screen, uAmount), c.a);
}
